// *** WITHOUT SPRING: Raw JDBC — error-prone, verbose, connection leak risk ***
package com.bank.rtgs.service;

import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import javax.sql.DataSource;
import java.math.BigDecimal;
import java.sql.*;

@Service
@RequiredArgsConstructor
@Slf4j
public class ManualJdbcTransferService {

    private final DataSource dataSource;  // HikariCP pool — but TX managed manually

    /**
     * MANUAL JDBC transaction: 25+ lines of boilerplate for what @Transactional does in 1 line.
     *
     * RISKS:
     * 1. Forget rollback in catch → partial data committed
     * 2. Forget close connection in finally → CONNECTION LEAK → pool exhausted → app crashes
     * 3. Forget setAutoCommit(false) → each statement commits individually → no atomicity
     * 4. No propagation, isolation, timeout, readOnly support
     * 5. No AOP — cross-cutting concerns must be manually coded
     */
    public String transferManual(String fromId, String toId, BigDecimal amount) {
        Connection connection = null;
        try {
            // Step 1: Get connection from pool
            connection = dataSource.getConnection();

            // Step 2: Disable auto-commit (BEGIN TRANSACTION)
            connection.setAutoCommit(false);

            // Step 3: Execute SQL — debit
            try (PreparedStatement debitStmt = connection.prepareStatement(
                    "UPDATE accounts SET balance = balance - ? WHERE account_id = ? AND balance >= ?")) {
                debitStmt.setBigDecimal(1, amount);
                debitStmt.setString(2, fromId);
                debitStmt.setBigDecimal(3, amount);
                int rows = debitStmt.executeUpdate();
                if (rows == 0) throw new RuntimeException("Debit failed: insufficient balance or account not found");
            }

            // Step 4: Execute SQL — credit
            try (PreparedStatement creditStmt = connection.prepareStatement(
                    "UPDATE accounts SET balance = balance + ? WHERE account_id = ?")) {
                creditStmt.setBigDecimal(1, amount);
                creditStmt.setString(2, toId);
                int rows = creditStmt.executeUpdate();
                if (rows == 0) throw new RuntimeException("Credit failed: account not found");
            }

            // Step 5: COMMIT
            connection.commit();
            log.info("[MANUAL] Transfer committed: {} → {} Rs.{}", fromId, toId, amount);
            return "COMMITTED";

        } catch (Exception e) {
            // Step 6: ROLLBACK on error (easy to forget!)
            if (connection != null) {
                try {
                    connection.rollback();
                    log.warn("[MANUAL] Transfer rolled back: {}", e.getMessage());
                } catch (SQLException rollbackEx) {
                    log.error("[MANUAL] Rollback FAILED: {}", rollbackEx.getMessage());
                }
            }
            throw new RuntimeException("Transfer failed: " + e.getMessage(), e);

        } finally {
            // Step 7: CLOSE connection (critical — leak if missed!)
            if (connection != null) {
                try {
                    connection.setAutoCommit(true);  // reset before returning to pool
                    connection.close();               // returns to HikariCP pool
                } catch (SQLException closeEx) {
                    log.error("[MANUAL] Close FAILED: {}", closeEx.getMessage());
                    // Connection LEAKED if this fails — pool slowly exhausts
                }
            }
        }
        // 40+ lines for what @Transactional does in 1 annotation!
    }
}
