// *** WITH SPRING: @Transactional — 1 annotation, proxy handles everything ***
package com.bank.rtgs.service;

import com.bank.rtgs.model.Account;
import com.bank.rtgs.repository.AccountRepository;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.math.BigDecimal;

@Service
@RequiredArgsConstructor
@Slf4j
public class SpringTransferService {

    private final AccountRepository accountRepo;

    /**
     * @Transactional: ONE annotation replaces 40 lines of manual JDBC.
     * The PROXY does exactly what ManualJdbcTransferService does manually:
     * 1. getConnection()
     * 2. setAutoCommit(false)
     * 3. Call this method
     * 4. commit() on success / rollback() on RuntimeException
     * 5. close() connection (always — in a finally equivalent)
     *
     * PLUS: propagation, isolation, timeout, readOnly, rollbackFor
     * PLUS: connection bound to thread (multiple repo calls share ONE connection)
     * PLUS: AOP integration (@Cacheable, @Async can compose with TX)
     */
    @Transactional(rollbackFor = Exception.class, timeout = 10)
    public String transfer(String fromId, String toId, BigDecimal amount) {
        Account from = accountRepo.findById(fromId)
            .orElseThrow(() -> new IllegalArgumentException("Not found: " + fromId));
        Account to = accountRepo.findById(toId)
            .orElseThrow(() -> new IllegalArgumentException("Not found: " + toId));

        from.debit(amount);    // throws if insufficient → proxy rollback
        to.credit(amount);

        accountRepo.save(from);
        accountRepo.save(to);

        log.info("[SPRING] Transfer committed: {} → {} Rs.{}", fromId, toId, amount);
        return "COMMITTED";
        // Proxy: commit(). Connection returned to pool. ALWAYS. Even on error.
    }
}
