package com.bank.rtgs.controller;

import com.bank.rtgs.service.*;
import lombok.RequiredArgsConstructor;
import org.springframework.web.bind.annotation.*;
import java.math.BigDecimal;

@RestController
@RequestMapping("/api/v1/rtgs")
@RequiredArgsConstructor
public class RtgsController {

    private final ManualJdbcTransferService manualService;
    private final SpringTransferService springService;

    @PostMapping("/manual")
    public String transferManual(@RequestParam String from, @RequestParam String to, @RequestParam BigDecimal amount) {
        return manualService.transferManual(from, to, amount);
    }

    @PostMapping("/spring")
    public String transferSpring(@RequestParam String from, @RequestParam String to, @RequestParam BigDecimal amount) {
        return springService.transfer(from, to, amount);
    }
}
